    required String cwd,
    required String sessionId,
    String? sessionName,
  }) => launchMailboxWake(
    env: _env,
    wakeExecutable: config.wakeExecutable,
    cwd: cwd,
    sessionId: sessionId,
    sessionName: sessionName,
  );

  late final SubagentManager _subagentManager;

