    final result = quotaService.peek(providerId);
    if (result != null && result.quota == null) return '';
    final badgeText = formatQuotaBadge(
      shortName: _quotaBadgeTag(providerId),
      quota: result?.quota,
      now: DateTime.now().toUtc(),
