      final clock = _ScriptClock(0);
      final meter = _meter(clock);
      expect(meter.tokensPerSecondAvg(0), isNull);
      expect(meter.tokensPerSecondAvg(100), isNull); // no active time yet
      meter.observeDelta(40);
